package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionSynchronizationManager;
/** Real dual-budget reservation within the authenticated action transaction. Reserving never grants a send. */
public final class FormalInvocationReservations {
 private final FormalVerificationJobs jobs;private final FormalInvocationCurrent current;private final FormalInvocationBudget budgets;private final FormalInvocationSchema schema;private final JdbcTemplate db;
 public FormalInvocationReservations(FormalVerificationJobs jobs,FormalInvocationCurrent current,FormalInvocationBudget budgets,FormalInvocationSchema schema,DataSource data){this.jobs=jobs;this.current=current;this.budgets=budgets;this.schema=schema;db=new JdbcTemplate(data);db.setQueryTimeout(5);}
 public static final class Reserved {
  private final String invocation,verification,run,step,action,requestHash,status;private final BigInteger lease;
  private Reserved(String invocation,FormalInvocationBinding j,BigInteger lease,String status){this.invocation=invocation;verification=j.verification();run=j.run();step=j.step();action=j.action();requestHash=j.requestHash();this.lease=lease;this.status=status;}
  public String invocationId(){return invocation;}public String verificationId(){return verification;}public String runId(){return run;}public String stepId(){return step;}public String actionId(){return action;}public String requestBodySha256(){return requestHash;}public BigInteger leaseGeneration(){return lease;}public String status(){return status;}
 }
 public Reserved reserveExpected(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,String model,String context,JsonNode parameters)throws Exception{requireWorker(a,worker);var job=new FormalInvocationBinding.Verification(jobs.byRun(worker.tenantId(),worker.runId()));if(!job.model().equals(model)||!job.context().equals(context)||!schema.canonical(schema.parse(job.request()).required("request_parameters")).equals(schema.canonical(parameters)))bad();return reserve(a,worker);}
 public Reserved reserve(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker)throws Exception{
  requireWorker(a,worker);var job=new FormalInvocationBinding.Verification(jobs.byRun(worker.tenantId(),worker.runId()));if(!job.step().equals(worker.stepId())||!job.action().equals(worker.actionId())||!job.actor().equals(worker.initiatorId())||!job.principal().equals(worker.principalId()))denied();
  var authorized=current.require(a,((FormalInvocationBinding.Verification)job).original(),true);return reserve(a,worker,job,new Authorization(authorized.request(),authorized.model(),authorized.price(),authorized.credentialReferenceId(),authorized.credentialRevision(),authorized.authorizationSha256(),authorized::requireCurrent,null,null,null,null,null));
 }
 /** TASK uses the same dual reservations and immutable invocation journal, never a verification job. */
 public Reserved reserveTask(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,TaskInvocationService.Prepared prepared)throws Exception {
  requireWorker(a,worker);prepared.requireCurrent(a,worker);var job=prepared.binding();return reserve(a,worker,job,new Authorization(prepared.request(),prepared.model(),prepared.price(),prepared.credentialReferenceId(),prepared.credentialRevision(),prepared.authorizationSha256(),()->prepared.requireCurrent(a,worker),prepared,null,null,null,null));
 }
 public Reserved reservePlanDraft(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,TaskPlanDraftInvocationService.Prepared prepared)throws Exception {
  requireWorker(a,worker);prepared.requireCurrent(a,worker);return reserve(a,worker,prepared.binding(),new Authorization(prepared.request(),prepared.model(),prepared.price(),prepared.credentialReferenceId(),prepared.credentialRevision(),prepared.authorizationSha256(),()->prepared.requireCurrent(a,worker),null,prepared,null,null,null));
 }
 public Reserved reserveSectionWriter(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,TaskSectionWriterInvocationService.Prepared prepared)throws Exception {
  requireWorker(a,worker);prepared.requireCurrent(a,worker);return reserve(a,worker,prepared.binding(),new Authorization(prepared.request(),prepared.model(),prepared.price(),prepared.credentialReferenceId(),prepared.credentialRevision(),prepared.authorizationSha256(),()->prepared.requireCurrent(a,worker),null,null,prepared,null,null));
 }
 public Reserved reserveSourceVerifier(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,TaskSourceVerifierInvocationService.Prepared prepared)throws Exception {
  requireWorker(a,worker);prepared.requireCurrent(a,worker);return reserve(a,worker,prepared.binding(),new Authorization(prepared.request(),prepared.model(),prepared.price(),prepared.credentialReferenceId(),prepared.credentialRevision(),prepared.authorizationSha256(),()->prepared.requireCurrent(a,worker),null,null,null,prepared,null));
 }
 public Reserved reserveDocumentReview(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,DocumentReviewInvocationService.Prepared prepared)throws Exception {
  requireWorker(a,worker);prepared.requireCurrent(a,worker);return reserve(a,worker,prepared.binding(),new Authorization(prepared.request(),prepared.model(),prepared.price(),prepared.credentialReferenceId(),prepared.credentialRevision(),prepared.authorizationSha256(),()->prepared.requireCurrent(a,worker),null,null,null,null,prepared));
 }
 @FunctionalInterface private interface Current {void require()throws Exception;}
 private record Authorization(JsonNode request,JsonNode model,FormalInvocationPricing.Schedule price,String credentialReferenceId,String credentialRevision,String authorizationSha256,Current current,TaskInvocationService.Prepared task,TaskPlanDraftInvocationService.Prepared plan,TaskSectionWriterInvocationService.Prepared writer,TaskSourceVerifierInvocationService.Prepared verifier,DocumentReviewInvocationService.Prepared document){void requireCurrent()throws Exception{current.require();}}
 private Reserved reserve(EnterpriseAccess.Admission a,RunTokenAuthority.Admission worker,FormalInvocationBinding job,Authorization authorized)throws Exception {
  return reserve(a,worker.leaseGeneration(),worker.serviceUri(),job,authorized,null);
 }
 public Reserved reserveEvaluation(EnterpriseAccess.Admission a,FormalEvaluationInvocationService.Prepared p)throws Exception {
  p.requireCurrent(a);return reserve(a,p.generation(),p.serviceUri(),p.binding(),new Authorization(p.request(),p.model(),p.price(),p.credentialReferenceId(),p.credentialRevision(),p.authorizationSha256(),()->p.requireCurrent(a),null,null,null,null,null),p);
 }
 private Reserved reserve(EnterpriseAccess.Admission a,BigInteger generation,String service,FormalInvocationBinding job,Authorization authorized,FormalEvaluationInvocationService.Prepared evaluation)throws Exception {
  var request=authorized.request();var old=find(job,true);if(old.isPresent()){verify(job,old.get());return new Reserved(old.get().id,job,old.get().lease,old.get().status);}
  var lock=one(db.query("SELECT invocation_id FROM step_action_binding WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND kind='MODEL_CALL' AND arguments_sha256=? AND input_sha256=? LIMIT 2 FOR UPDATE",(r,n)->Optional.ofNullable(r.getString(1)),job.tenant(),job.run(),job.step(),job.action(),job.requestHash(),job.inputHash()));if(lock.isPresent())bad();
  var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));var input=new BigInteger(request.required("maximum_input_tokens").textValue());var output=request.required("request_parameters").required("max_output_tokens").bigIntegerValue();var upper=FormalInvocationPricing.upperAmount(authorized.price(),input,output);var maximumTokens=input.add(output);if(maximumTokens.signum()<0||maximumTokens.bitLength()>64)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);
  var enterprise=basis(request.required("enterprise_budget_basis"));var parent=basis(request.required("parent_budget_basis"));var accounts=budgets.reserve(a,job.project(),List.of(enterprise,parent),authorized.price().currency(),upper,maximumTokens,now);
  String invocation=id();var values=meta(job,now);values.put("project_id",job.project());values.put("invocation_id",invocation);values.put("run_id",job.run());values.put("step_id",job.step());values.put("action_id",job.action());values.put("config_id",authorized.model().required("config_id").textValue());values.put("config_revision",job.model());values.put("credential_reference_id",authorized.credentialReferenceId());values.put("credential_revision",authorized.credentialRevision());values.put("verification_id",job.verification());values.put("context_manifest_id",job.context());values.put("price_version",authorized.price().priceVersion());values.put("currency",authorized.price().currency());values.put("request_parameters",schema.canonical(request.required("request_parameters")));values.put("input_sha256",job.inputHash());values.put("status","RESERVED");values.put("settlement_status","PENDING");values.put("dispatch_generation",0);values.put("lease_generation",generation);values.put("revision",1);values.put("updated_at",now);insert("invocation",values);
  Map<String,String> reservations=new HashMap<>();for(var account:accounts){var reservation=new LinkedHashMap<String,Object>();reservation.put("tenant_id",job.tenant());reservation.put("project_id",job.project());reservation.put("reservation_id",id());reservation.put("invocation_id",invocation);reservation.put("budget_id",account.budgetId());reservation.put("budget_revision",account.budgetRevision());reservation.put("currency",account.currency());reservation.put("upper_amount",upper);reservation.put("upper_tokens",maximumTokens);reservation.put("status","RESERVED");reservation.put("created_by",job.actor());reservation.put("created_at",now);reservation.put("classification",job.classification());reservation.put("revision",1);reservation.put("updated_at",now);insert("budget_reservation",reservation);reservations.put(account.budgetRevision(),(String)reservation.get("reservation_id"));}
  var snapshot=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("verification_id",job.verification()).put("job_dependency_sha256",job.dependenciesHash()).put("authorization_sha256",authorized.authorizationSha256()).put("lease_generation",generation.toString()).put("service_uri",service).put("maximum_tokens",maximumTokens.toString()).put("upper_amount",upper.toPlainString());
  if(job instanceof TaskInvocationRecords.Binding task){snapshot.set("task_binding",task.snapshot());snapshot.set("task_send_authorizations",authorized.task().sendAuthorizations());snapshot.set("task_output_commitment",authorized.task().outputCommitment(a,invocation));}
  if(job instanceof TaskPlanDraftInvocationRecords.Binding plan){snapshot.set("plan_draft_binding",plan.snapshot());snapshot.set("plan_draft_send_authorizations",authorized.plan().sendAuthorizations());snapshot.set("plan_draft_output_commitment",authorized.plan().outputCommitment(invocation));}
  if(job instanceof TaskSectionWriterInvocationRecords.Binding writer){snapshot.set("section_writer_binding",writer.snapshot());snapshot.set("section_writer_send_authorizations",authorized.writer().sendAuthorizations());snapshot.set("section_writer_output_commitment",authorized.writer().outputCommitment(invocation));}
  if(job instanceof TaskSourceVerifierInvocationRecords.Binding verifier){snapshot.set("source_verifier_binding",verifier.snapshot());snapshot.set("source_verifier_send_authorizations",authorized.verifier().sendAuthorizations());snapshot.set("source_verifier_output_commitment",authorized.verifier().outputCommitment(invocation));}
  if(job instanceof DocumentReviewInvocationRecords.Binding verifier){snapshot.set("document_review_binding",verifier.snapshot());snapshot.set("document_review_send_authorizations",authorized.document().sendAuthorizations());snapshot.set("document_review_output_commitment",authorized.document().outputCommitment(invocation));}
  if(evaluation!=null){snapshot.set("evaluation_binding",evaluation.binding().snapshot());snapshot.set("evaluation_send_authorizations",evaluation.sendAuthorizations());snapshot.set("evaluation_output_commitment",evaluation.outputCommitment(invocation));}
  var binding=meta(job,now);binding.put("project_id",job.project());binding.put("invocation_id",invocation);binding.put("canonical_request",job.request());binding.put("request_sha256",job.requestHash());var price=schema.parse(job.dependencies()).required("price");binding.put("canonical_price",schema.canonical(price));binding.put("price_sha256",schema.hash(price));binding.put("authorization_snapshot",schema.canonical(snapshot));binding.put("authorization_sha256",schema.hash(snapshot));binding.put("enterprise_reservation_id",reservations.get(enterprise.version_id()));binding.put("parent_reservation_id",reservations.get(parent.version_id()));insert("formal_invocation_binding",binding);
  if(db.update("UPDATE step_action_binding SET invocation_id=?,lease_generation=?,state='RESERVED',revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND step_id=? AND action_id=? AND invocation_id IS NULL AND state='BOUND'",invocation,generation,now,job.tenant(),job.run(),job.step(),job.action())!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var event=schema.parse(schema.canonical(Map.of("schema_version","1.0.0","invocation_id",invocation,"verification_id",job.verification(),"request_sha256",job.requestHash(),"binding",binding,"invocation",values)));audit(job,invocation,event,now);authorized.requireCurrent();var stored=find(job,true).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));verify(job,stored);return new Reserved(invocation,job,stored.lease,stored.status);
 }
 void requireRegistered(FormalVerificationJobs.Job job,String invocation)throws Exception{requireRegistered(new FormalInvocationBinding.Verification(job),invocation);}
 void requireRegistered(FormalInvocationBinding job,String invocation)throws Exception{var row=find(job,false).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));if(!invocation.equals(row.id))bad();verify(job,row);}
 private record Row(String id,String status,BigInteger lease,String request,String requestHash,String price,String priceHash,String authorization,String authorizationHash,String enterprise,String parent,LocalDateTime created){}
 private Optional<Row> find(FormalInvocationBinding j,boolean lock){var rows=db.query("SELECT i.invocation_id,i.status,i.lease_generation,b.canonical_request,b.request_sha256,b.canonical_price,b.price_sha256,b.authorization_snapshot,b.authorization_sha256,b.enterprise_reservation_id,b.parent_reservation_id,i.created_at FROM invocation i LEFT JOIN formal_invocation_binding b ON b.tenant_id=i.tenant_id AND b.invocation_id=i.invocation_id WHERE i.tenant_id=? AND i.run_id=? AND i.step_id=? AND i.action_id=? LIMIT 2"+(lock?" FOR UPDATE":""),(r,n)->new Row(r.getString(1),r.getString(2),r.getBigDecimal(3).toBigIntegerExact(),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11),r.getTimestamp(12).toLocalDateTime()),j.tenant(),j.run(),j.step(),j.action());if(rows.size()>1)bad();return rows.stream().findFirst();}
 private void verify(FormalInvocationBinding j,Row r)throws Exception{
  if(!j.request().equals(r.request)||!j.requestHash().equals(r.requestHash)||!schema.hash(schema.parse(r.price)).equals(r.priceHash)||!schema.hash(schema.parse(r.authorization)).equals(r.authorizationHash)||r.lease.signum()<=0||r.enterprise==null||r.parent==null||r.enterprise.equals(r.parent))bad();if(one(db.query("SELECT COUNT(*) FROM formal_invocation_binding WHERE tenant_id=? AND project_id=? AND invocation_id=? AND created_by=? AND created_at=? AND classification=? AND schema_version='1.0.0' AND schema_manifest_sha256=?",(rs,n)->rs.getInt(1),j.tenant(),j.project(),r.id,j.actor(),r.created,j.classification(),schema.manifestSha256()))!=1)bad();var authorization=schema.parse(r.authorization);var price=schema.parse(j.dependencies()).required("price");if(!schema.canonical(price).equals(r.price)||!j.dependenciesHash().equals(authorization.required("job_dependency_sha256").textValue())||!j.verification().equals(authorization.required("verification_id").textValue())||!r.lease.toString().equals(authorization.required("lease_generation").textValue()))bad();
  var request=schema.parse(j.request());for(var pair:List.of(Map.entry(r.enterprise,"enterprise_budget_basis"),Map.entry(r.parent,"parent_budget_basis"))){if(one(db.query("SELECT COUNT(*) FROM budget_reservation WHERE tenant_id=? AND project_id=? AND reservation_id=? AND invocation_id=? AND budget_revision=? AND upper_amount=? AND upper_tokens=? AND currency=? AND created_by=? AND created_at=? AND classification=?",(rs,n)->rs.getInt(1),j.tenant(),j.project(),pair.getKey(),r.id,request.required(pair.getValue()).required("version_id").textValue(),authorization.required("upper_amount").textValue(),authorization.required("maximum_tokens").textValue(),price.required("currency").textValue(),j.actor(),r.created,j.classification()))!=1)bad();}
  if(one(db.query("SELECT COUNT(*) FROM invocation i JOIN step_action_binding s ON s.tenant_id=i.tenant_id AND s.run_id=i.run_id AND s.step_id=i.step_id AND s.action_id=i.action_id WHERE i.tenant_id=? AND i.invocation_id=? AND i.verification_id=? AND i.config_revision=? AND i.context_manifest_id=? AND i.input_sha256=? AND i.created_by=? AND i.schema_version='1.0.0' AND i.schema_manifest_sha256=? AND s.invocation_id=i.invocation_id",(rs,n)->rs.getInt(1),j.tenant(),r.id,j.verification(),j.model(),j.context(),j.inputHash(),j.actor(),schema.manifestSha256()))!=1)bad();
  var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_reserved' AND request_id=? AND trace_id=? AND result='SUCCESS' AND schema_manifest_sha256=? LIMIT 2",(rs,n)->rs.getString(1),j.tenant(),j.actor(),r.id,j.verification(),schema.manifestSha256()));var event=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='model.invocation_reserved' LIMIT 2",(rs,n)->rs.getString(1),j.tenant(),r.id));if(!schema.canonical(schema.parse(audit)).equals(schema.canonical(schema.parse(event))))bad();var auditNode=schema.parse(audit);var recorded=auditNode.required("binding");
  var original=auditNode.required("invocation");var actual=one(db.query("SELECT JSON_OBJECT('config_id',config_id,'credential_reference_id',credential_reference_id,'credential_revision',credential_revision,'price_version',price_version,'currency',currency,'request_parameters',request_parameters,'classification',classification,'schema_manifest_sha256',schema_manifest_sha256) FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(rs,n)->rs.getString(1),j.tenant(),r.id));var loaded=schema.parse(actual);for(String field:List.of("config_id","credential_reference_id","credential_revision","price_version","currency","classification","schema_manifest_sha256"))if(!loaded.required(field).equals(original.required(field)))bad();if(!schema.canonical(loaded.required("request_parameters")).equals(original.required("request_parameters").textValue()))bad();if(!r.authorization.equals(recorded.required("authorization_snapshot").textValue())||!r.price.equals(recorded.required("canonical_price").textValue())||!r.request.equals(recorded.required("canonical_request").textValue())||!r.enterprise.equals(recorded.required("enterprise_reservation_id").textValue())||!r.parent.equals(recorded.required("parent_reservation_id").textValue()))bad();
 }
 private void audit(FormalInvocationBinding j,String invocation,JsonNode event,LocalDateTime now)throws Exception{var a=meta(j,now);a.put("project_id",j.project());a.put("audit_id",id());a.put("subject_id",j.actor());a.put("action","model.invocation_reserved");a.put("resource_ref",schema.canonical(event));a.put("result","SUCCESS");a.put("request_id",invocation);a.put("trace_id",j.verification());insert("audit_event",a);insert("outbox_event",Map.of("tenant_id",j.tenant(),"event_id",id(),"aggregate_id",invocation,"aggregate_revision",1,"event_type","model.invocation_reserved","payload",schema.canonical(event),"occurred_at",now));}
 private Map<String,Object> meta(FormalInvocationBinding j,LocalDateTime now){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schema.manifestSha256());m.put("created_by",j.actor());m.put("created_at",now);m.put("classification",j.classification());return m;}
 private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
 private static void requireWorker(EnterpriseAccess.Admission a,RunTokenAuthority.Admission w){if(!TransactionSynchronizationManager.isActualTransactionActive()||!a.actorId().equals(w.initiatorId())||!a.context().tenant_id().equals(w.tenantId())||!TenantScope.requireCurrent().subjectId().equals(w.initiatorId())||w.leaseGeneration().signum()<=0)denied();}
 private static PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(n.required("version_id").textValue(),n.required("content_sha256").textValue());}private static String id(){return UUID.randomUUID().toString();}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void denied(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
